import React, { useEffect, useState } from "react";
import axios from "axios";
import Navbar from "../components/Navbar";

export default function Tasks() {
  const [tasks, setTasks] = useState([]);
  const [title, setTitle] = useState("");

  const fetchTasks = async () => {
    const res = await axios.get("http://localhost:9000/api/tasks");
    setTasks(res.data);
  };

  useEffect(() => {
    fetchTasks();
  }, []);

  const createTask = async () => {
    await axios.post("http://localhost:9000/api/tasks", {
      title,
      status: "Pending",
    });

    setTitle("");
    fetchTasks();
  };

  const completeTask = async (id) => {
    await axios.put(`http://localhost:9000/api/tasks/${id}`, {
      status: "Completed",
    });

    fetchTasks();
  };

  return (
    <>
      <Navbar />

      <div style={styles.container}>
        <h1>Tasks</h1>

        <div style={styles.form}>
          <input
            style={styles.input}
            placeholder="Task Title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />

          <button style={styles.button} onClick={createTask}>
            Add Task
          </button>
        </div>

        {tasks.map((task) => (
          <div style={styles.card} key={task._id}>
            <h3>{task.title}</h3>
            <p>Status: {task.status}</p>

            {task.status !== "Completed" && (
              <button
                style={styles.smallButton}
                onClick={() => completeTask(task._id)}
              >
                Mark Completed
              </button>
            )}
          </div>
        ))}
      </div>
    </>
  );
}

const styles = {
  container: {
    width: "600px",
    margin: "40px auto",
  },
  form: {
    background: "white",
    padding: "25px",
    borderRadius: "12px",
    boxShadow: "0px 0px 10px #ccc",
  },
  input: {
    width: "100%",
    padding: "12px",
    marginTop: "10px",
  },
  button: {
    width: "100%",
    padding: "12px",
    marginTop: "15px",
    background: "#4f46e5",
    color: "white",
    border: "none",
  },
  card: {
    background: "white",
    padding: "20px",
    marginTop: "15px",
    borderRadius: "10px",
    boxShadow: "0px 0px 8px #ddd",
  },
  smallButton: {
    padding: "10px",
    background: "green",
    color: "white",
    border: "none",
    borderRadius: "5px",
  },
};
